def validate_context(row,root=ROOT):
    clean={k:v for k,v in row.items() if k not in ['source_file','source_pointer','source_sha256']}
    if clean!=EXPECTED_REFERENCES.get(row['id']):raise ValueError('Unreviewed calculated monthly velocity descriptor')


def build(root=ROOT):
    prior=previous.build(root)
    if prior!=json.loads((root/previous.OUTPUT).read_bytes()):raise ValueError('Prior register no longer reproduces')
    pins=dict(prior['input_sha256'])
    for p in [previous.OUTPUT,previous.CSV,'analysis/build_current_depth_register_v37.py',RULES,SOURCE,MEMBERS,MEMBER_OUTPUT,'research/source-data/leeuwin-seasonal-depth-v1/seasonal-candidate.json','research/leeuwin-seasonal-depth-operator-v1.json','research/source-data/leeuwin-seasonal-depth-v1/sensitivity-v1.json']:
        pins[p]=hashlib.sha256((root/p).read_bytes()).hexdigest()
    source=json.loads((root/SOURCE).read_bytes());rules=json.loads((root/RULES).read_bytes())
    if source['previous_register_sha256']!=pins[previous.OUTPUT]:raise ValueError('Prior pin mismatch')
    for p,digest in source['source_input_sha256'].items():
        if pins[p]!=digest:raise ValueError('Retained source XML changed')
    evidence=list(prior['evidence']);seen={r['id'] for r in evidence};identities={r['entity_id'] for r in prior['records']}
    for i,row in enumerate(source['references']):
        validate_reference(row,identities,rules['metric_types']);validate_context(row,root)
        if row['id'] in seen:raise ValueError('Duplicate source reference')
        seen.add(row['id']);evidence.append(dict(row,source_file=SOURCE,source_pointer=f'/references/{i}',source_sha256=pins[SOURCE]))
    records=[]
    for raw in prior['records']:
        row=dict(raw);row['depth_reference_ids']=[r['id'] for r in evidence if r['entity_id']==row['entity_id']]
        row['status']='scoped_depth_reference' if row['depth_reference_ids'] else 'not_yet_assessed';records.append(row)
    owners=sum(bool(r['depth_reference_ids']) for r in records)
    return {'schema':'osw.current-depth-register.v38','status':'LEEUWIN_LOCAL_CALCULATED_MONTHLY_ZERO_DESCRIPTORS',
            'rules_file':RULES,'generator_file':'analysis/build_current_depth_register_v38.py',
            'generator_sha256':hashlib.sha256((root/'analysis/build_current_depth_register_v38.py').read_bytes()).hexdigest(),
            'input_sha256':pins,'previous_evidence_preserved':evidence[:len(prior['evidence'])]==prior['evidence'],
            'counts':{'identities':111,'depth_references':len(evidence),'identities_with_scoped_depth_reference':owners,
                      'identities_not_yet_assessed':111-owners,'whole_route_depth_profiles':0,'volume_estimates':0},
            'metric_counts':dict(sorted(Counter(r['metric'] for r in evidence).items())),
            'coverage_interpretation':prior['coverage_interpretation']+' Nine calculated local Leeuwin monthly mean-velocity zero-crossing descriptors retain their distinct derived metric. Three other months remain unknown; published approximate depths are unchanged. No physical bottom, complete seasonal envelope or whole-route profile follows.',
            'metadata_correction_file':prior.get('metadata_correction_file'),'metadata_correction_count':prior.get('metadata_correction_count',0),'member_depth_index_file':MEMBER_OUTPUT,'records':records,'evidence':evidence,'runtime_changed':False,'full_goal_complete':False}


def csv_bytes(document):
    columns=next(csv.reader(io.StringIO(previous.csv_bytes(document).decode('utf8'))))
    columns += [p for p in ['derived_profile_file', 'derived_profile_id', 'derived_profile_pointer', 'derived_profile_sha256', 'source_product_sha256', 'derivation_operator_file', 'derivation_operator_sha256', 'source_selected_daily_records', 'source_accepted_quality_flags', 'local_along_mean_bearing_degrees_true', 'computed_zero_crossing_depth_m', 'interpolation_bracket_m', 'display_rounding_m', 'calculated_descriptor_not_published_depth','source_cross_section_area_km2', 'source_cross_section_area_role', 'source_distance_offshore_km', 'source_distance_offshore_is_current_width', 'source_model_grid_rotation_clockwise_degrees', 'source_signed_alongshore_isotach_m_s', 'model_simulation_period', 'source_record_vertical_datum', 'normalization_file', 'normalization_rule_id','core_latitude_relation', 'source_ship_section_count', 'source_ship_section_year_bounds', 'surface_mean_completion', 'section_latitude_degrees_north','source_record_period', 'source_record_period_has_gaps', 'comparison_products', 'ADCP_velocities_assimilated_in_ECCOv4r4', 'source_raw_ADCP_bin_size_m', 'source_raw_ADCP_sampling_seconds', 'source_processed_ADCP_level_spacing_m', 'source_study_velocity_averaging_hours','source_survey_periods', 'source_ADCP_frequency_kHz', 'source_displayed_ADCP_limit_m', 'station_profile_averaging_definition', 'source_figure4_velocity_quantity', 'source_citation', 'range_interpretation', 'upper_boundary_m', 'lower_boundary_m', 'thickness_m', 'uncertainty_m', 'annual_range_m', 'calendar_months', 'observed_period', 'independent_observation_count_claimed', 'whole_current_representative', 'volume_eligible', 'physical_state_join_eligible', 'seasonal_playback_eligible', 'annual_extrema_eligible','source_research_vessel','source_STF_bracketing_latitude_range_degrees_north','source_STF_bracket_longitude_degrees_east','source_depth_phrase','source_speed_context_cm_s','geostrophic_reference_definition','source_table2_reference_depth_summary_m','source_table2_reference_flag','figure5_reference_policy','source_site_id'] if p not in columns]
    out=io.StringIO(newline='');writer=csv.DictWriter(out,fieldnames=columns,lineterminator='\n',extrasaction='ignore');writer.writeheader()
    for raw in document['evidence']:
        row=dict(raw)
        if row.get('section_sampling_window'):
            row['section_window_start']=row['section_sampling_window']['start'];row['section_window_end']=row['section_sampling_window']['end']
        for key,value in list(row.items()):
            if isinstance(value,(dict,list)):row[key]=json.dumps(value,ensure_ascii=False,separators=(',',':'))
        writer.writerow(row)
    return out.getvalue().encode('utf8')
